// Arknights: Endfield-style theme for DeepSeek Harness (unofficial fan work).
// Presentation only: no network access, no credentials, no app-state writes.
// Generated by build.mjs from src/theme.js and src/styles.css; edit those.
declare const __PLUGIN_CSS__: string;

interface PluginContext {
  effect: (effect: () => () => void, label?: string) => void;
}

export const inject: string[] = [];

export function apply(ctx: PluginContext) {
  ctx.effect(() => {
    const root = document.documentElement;
    const style = document.createElement('style');
    style.dataset.endfieldTheme = 'true';
    style.textContent = __PLUGIN_CSS__;
    document.head.appendChild(style);
    root.dataset.endfieldTheme = 'on';
    const stop = start(root);
    return () => {
      stop();
      delete root.dataset.endfieldTheme;
      document.querySelectorAll('.ef-masthead, .ef-signal-rail, .ef-appearance').forEach((el) => el.remove());
      style.remove();
    };
  }, 'endfield-theme');
}

function start(root: HTMLElement): () => void {
  // Generated contour artwork: no external image requests and no per-frame animation.
  const paths: string[] = [];
  for (let k = 3; k < 47; k++) {
    const points: string[] = [];
    for (let j = 0; j <= 160; j++) {
      const t = j / 160 * Math.PI * 2, r = k * 15;
      const rr = r * (1 + .075 * Math.sin(3 * t + .8) + .045 * Math.sin(7 * t + r / 180) + .03 * Math.cos(11 * t));
      points.push(`${j ? 'L' : 'M'}${(710 + rr * 1.37 * Math.cos(t)).toFixed(1)},${(120 + rr * .73 * Math.sin(t)).toFixed(1)}`);
    }
    paths.push(`<path d="${points.join('')}Z"/>`);
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 400"><g fill="none" stroke="#77836c" stroke-width=".8">${paths.join('')}</g></svg>`;
  root.style.setProperty('--ef-topography', `url("data:image/svg+xml,${encodeURIComponent(svg)}")`);
  function node(tag: string, cls: string, content?: string): HTMLElement {
    const el = document.createElement(tag); el.className = cls;
    if (content) el.textContent = content;
    return el;
  }
  let scheduled = false;
  let appearanceRequestedUntil = 0;
  function mount() {
    scheduled = false;
    if (appearanceRequestedUntil > Date.now()) {
      const panel = document.querySelector('.VOzbGW_panel');
      const cubes = panel?.querySelector<HTMLElement>('._8HJdBW_cubeRow');
      if (cubes) { appearanceRequestedUntil = 0; cubes.scrollIntoView({ block: 'nearest' }); }
      else {
        const general = panel?.querySelector('.VOzbGW_navCell');
        if (general && general.getAttribute('aria-current') !== 'true') (general as HTMLElement).click();
      }
    }
    const center = document.querySelector('.pI_x6G_centerCol');
    if (center && !center.querySelector(':scope > .ef-masthead')) {
      const head = node('div', 'ef-masthead');
      const art = node('span', 'ef-background-word', 'DEEPFIELD'); art.setAttribute('aria-hidden', 'true');
      head.append(art, node('span', 'ef-eyebrow', 'DSH / WEB TERMINAL'), node('div', 'ef-session-title', '工作终端'), node('span', 'ef-subtitle', 'OVER THE FRONTIER / INTO THE FRONT'));
      center.prepend(head);
    }
    if (center && !center.querySelector(':scope > .ef-signal-rail')) {
      const rail = node('div', 'ef-signal-rail'); rail.setAttribute('aria-hidden', 'true');
      rail.append(node('span', 'ef-rail-mark', '//'), node('span', 'ef-rail-type', 'TERMINAL / FIELD NOTES'), node('span', 'ef-rail-end', '+'));
      center.append(rail);
    }
    const selected = document.querySelector('.YDXeBa_sessionRow[aria-selected="true"] .YDXeBa_title');
    const title = center?.querySelector('.ef-session-title');
    const currentCrumb = document.querySelector('.wSkVaW_crumbCurrent');
    const value = currentCrumb?.textContent?.trim() || selected?.textContent?.trim() || '工作终端';
    if (title && title.textContent !== value) { title.textContent = value; title.title = value; }
    const sidebar = document.querySelector<HTMLElement>('.hHd-Xa_root');
    const footer = sidebar?.querySelector<HTMLElement>('.hHd-Xa_settingsArea');
    if (sidebar && footer && !sidebar.querySelector('.ef-appearance')) {
      const shortcut = node('button', 'ef-appearance') as HTMLButtonElement; shortcut.type = 'button';
      shortcut.setAttribute('aria-label', '外观设置：浅色、深色或跟随系统');
      const icon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      icon.setAttribute('viewBox', '0 0 20 20'); icon.setAttribute('width', '16'); icon.setAttribute('height', '16'); icon.setAttribute('aria-hidden', 'true');
      const circle = document.createElementNS(icon.namespaceURI, 'circle');
      for (const [k,v] of Object.entries({cx:10,cy:10,r:7,fill:'none',stroke:'currentColor','stroke-width':1.4})) circle.setAttribute(k,String(v));
      const half = document.createElementNS(icon.namespaceURI, 'path'); half.setAttribute('d','M10 3a7 7 0 0 0 0 14Z');half.setAttribute('fill','currentColor');icon.append(circle,half);
      shortcut.append(icon,node('span','ef-appearance-label','外观'),node('span','ef-appearance-options','浅色 / 深色 / 自动'));
      shortcut.addEventListener('click', () => {
        // Delegate to the real application Settings, keeping its persisted preference authoritative.
        const trigger = footer.querySelector<HTMLElement>('button');
        if (trigger) { appearanceRequestedUntil = Date.now() + 3000; trigger.click(); }
      });
      footer.before(shortcut);
    }
  }
  const observer = new MutationObserver(records => {
    // Only mount decorations after React navigation/remount, never rewrite app-owned content.
    if (!scheduled && records.some(r => r.type === 'childList' || r.type === 'characterData' || r.attributeName === 'aria-selected')) { scheduled = true; requestAnimationFrame(mount); }
  });
  observer.observe(document.getElementById('root') || document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['aria-selected'] });
  mount();
  return () => { observer.disconnect(); };
}

